/**
 * Every rule the schemas state, written out by hand, then held three ways.
 *
 * 1. The published schemas must state exactly this rulebook. The drift test
 *    only checks that the files match the code, so a rule weakened in the code
 *    and regenerated passes it; this table cannot be regenerated by a command,
 *    so weakening a rule means editing it here, in plain sight.
 * 2. Each rule is broken on every place it applies in every valid fixture,
 *    and exactly that field must be named. A rule removed from the code turns
 *    its cases red even if the table were edited to match.
 * 3. The accept side: every field appears in some valid fixture, every
 *    allowed value of every list appears, and every true-or-false field is
 *    seen both ways, so cutting an allowed value or dropping a field rejects a
 *    valid fixture.
 *
 * Patterns are pinned by name: each must be one of the named patterns, whose
 * examples are in pattern-examples.ts and tested in patterns.test.ts.
 */
import { describe, expect, it } from 'vitest';
import { loadFixtures, validatorFor, type Fixture } from './fixtures.ts';
import { FIRST_REJECTED } from './pattern-examples.ts';
import { ruleTable, type Rule } from './rule-table.ts';
import { PUBLISHED, publishedSchema } from './schemas.ts';

