type Json = Record<string, unknown>;
const isRecord = (v: unknown): v is Json =>
  typeof v === 'object' && v !== null && !Array.isArray(v);
const clone = <T>(v: T): T => structuredClone(v);

/** As the validator writes a field: `nodes[2].sources[0].edition`. */
function render(path: readonly (string | number)[]): string {
  return path.reduce<string>(
    (out, s) => (typeof s === 'number' ? `${out}[${s}]` : out === '' ? s : `${out}.${s}`),
    '',
  );
}

interface Instance {
  rulePath: string;
  path: (string | number)[];
  value: unknown;
}

/** Every place in a document that a rule in the table applies to. */
function instances(
  table: Record<string, Rule>,
  value: unknown,
  rulePath = '',
  path: (string | number)[] = [],
): Instance[] {
  if (!(rulePath in table)) return [];
  const found: Instance[] = [{ rulePath, path, value }];
  if (Array.isArray(value)) {
    (value as unknown[]).forEach((item, i) =>
      found.push(...instances(table, item, `${rulePath}[]`, [...path, i])),
    );
  } else if (isRecord(value)) {
    for (const [key, child] of Object.entries(value)) {
      found.push(
        ...instances(table, child, rulePath === '' ? key : `${rulePath}.${key}`, [...path, key]),
      );
    }
  }
  return found;
}

/** Replace the value at `path` in a copy of `doc`; `undefined` deletes it. */
function changed(doc: unknown, path: readonly (string | number)[], next: unknown): unknown {
  if (path.length === 0) return next;
  const copy = clone(doc);
  let parent = copy as Json | unknown[];
  for (const s of path.slice(0, -1))
    parent = (parent as Record<string | number, unknown>)[s] as Json;
  const last = path[path.length - 1] as string | number;
  if (next === undefined && !Array.isArray(parent)) delete parent[last as string];
  else (parent as Record<string | number, unknown>)[last] = next;
  return copy;
}

const WRONG_TYPE: Record<string, unknown> = {
  string: 7,
  number: 'x',
  integer: 'x',
  boolean: 'yes',
  array: {},
  object: [],
};

interface Case {
  label: string;
  doc: unknown;
  expect: string;
}

/** Documents that each break exactly one rule at one place, and the field each must name. */
function cases(rule: Rule, at: Instance, doc: unknown): Case[] {
  const out: Case[] = [];
  const here = render(at.path);
  const add = (what: string, next: unknown, field = here) =>
    out.push({
      label: `${here || '(document)'}: ${what}`,
      doc: changed(doc, at.path, next),
      expect: field,
    });
  const value = at.value;

  if (rule.type !== undefined) add(`wrong type for ${rule.type}`, WRONG_TYPE[rule.type]);
  if (rule.named !== undefined) add(`breaks ${rule.named}`, FIRST_REJECTED[rule.named]);
  if (rule.enum !== undefined) add('a value not in the list', 'not-an-allowed-value');
  if (rule.minimum !== undefined)
    add('below the minimum', rule.type === 'integer' ? rule.minimum - 1 : rule.minimum - 0.5);
  if (rule.maximum !== undefined)
    add('above the maximum', rule.type === 'integer' ? rule.maximum + 1 : rule.maximum + 0.5);
  if (Array.isArray(value)) {
    const items = value as unknown[];
    if (rule.minItems !== undefined)
      add(`fewer than ${rule.minItems} items`, items.slice(0, rule.minItems - 1));
    if (rule.uniqueItems && items.length > 0) {
      add('a repeated item', [...items, clone(items[0])], render([...at.path, items.length]));
    }
  }
  if (isRecord(value)) {
    for (const key of rule.required ?? []) {
      if (key in value) add(`without ${key}`, omit(value, key), render([...at.path, key]));
    }
    if (rule.closed)
      add(
        'an unknown field',
        { ...value, unexpected_field: 1 },
        render([...at.path, 'unexpected_field']),
      );
    for (const union of [rule.anyOf, rule.oneOf]) {
      if (union !== undefined)
        add(
          `without any of ${union.join(', ')}`,
          union.reduce((v, k) => omit(v, k), value),
        );
    }
    for (const [type, keys] of Object.entries(rule.requiredWhen ?? {})) {
      if (value.type !== type) continue;
      for (const key of keys) {
        if (key in value)
          add(`a ${type} without ${key}`, omit(value, key), render([...at.path, key]));
      }
    }
    for (const [key, [other]] of Object.entries(rule.together ?? {})) {
      if (other !== undefined && key in value && other in value) {
        add(`${key} without ${other}`, omit(value, other), render([...at.path, other]));
      }
    }
  }
  return out;
}

function omit(value: Json, key: string): Json {
  return Object.fromEntries(Object.entries(value).filter(([k]) => k !== key));
}

const valid = loadFixtures('valid');
const bySchema = (name: string): Fixture[] => valid.filter((f) => f.schema === name);

describe('the published schemas state exactly the rulebook', () => {
  for (const entry of PUBLISHED) {
    it(entry.name, () => {
      expect(ruleTable(publishedSchema(entry))).toEqual(RULES[entry.name]);
    });
  }
});

describe('every rule, broken wherever it applies, names exactly its field', () => {
  for (const entry of PUBLISHED) {
    const table = RULES[entry.name] ?? {};
    for (const fixture of bySchema(entry.name)) {
      const all = instances(table, fixture.value).flatMap((at) =>
        cases(table[at.rulePath] ?? {}, at, fixture.value),
      );
      it.each(all.map((c) => [c.label, c] as const))(`${fixture.file} → %s`, (_label, c) => {
        const result = validatorFor(fixture)(c.doc);
        expect(result.ok).toBe(false);
        expect(result.ok ? [] : [...new Set(result.issues.map((i) => i.path))]).toEqual([c.expect]);
      });
    }
  }
});

describe('the valid fixtures exercise every field and every allowed value', () => {
  for (const entry of PUBLISHED) {
    const table = RULES[entry.name] ?? {};
    const seen = bySchema(entry.name).flatMap((f) => instances(table, f.value));

    it(`${entry.name}: every field appears`, () => {
      const present = new Set(seen.map((s) => s.rulePath));
      expect(Object.keys(table).filter((p) => !present.has(p))).toEqual([]);
    });

    it(`${entry.name}: every allowed value appears, and every true-or-false field both ways`, () => {
      const missing: string[] = [];
      for (const [path, rule] of Object.entries(table)) {
        const values = new Set(seen.filter((s) => s.rulePath === path).map((s) => s.value));
        const wanted = rule.enum ?? (rule.type === 'boolean' ? [true, false] : []);
        for (const v of wanted) if (!values.has(v)) missing.push(`${path} = ${String(v)}`);
      }
      expect(missing).toEqual([]);
    });
  }
});
